  'ssc.sigAssist': { en: 'Fetch the signature and squeeze it into the 140×60 strip without losing the hand.', hi: 'हस्ताक्षर लाएँ और लिखावट बरकरार रखते हुए 140×60 पट्टी में समेटें।' },
