  'ssc.doneTitle': { en: 'Both files sit inside their boxes — the CGL form can proceed', hi: 'दोनों फ़ाइलें अपने बॉक्स में — CGL फ़ॉर्म आगे बढ़ सकता है' },
  'ssc.doneBody': { en: 'The photograph and signature passed the pixel and KB-band validators. The OTR profile now carries them into every SSC exam application.', hi: 'फोटो व हस्ताक्षर पिक्सेल व KB-बैंड जाँच में उत्तीर्ण हुए। OTR प्रोफ़ाइल अब इन्हें हर SSC परीक्षा आवेदन में ले जाएगी।' },
