  'nsp.dash': { en: 'NSP Student Dashboard', hi: 'NSP छात्र डैशबोर्ड' },
  'nsp.ayUpload': { en: 'AY 2026-27 · Upload Documents', hi: 'शै.व. 2026-27 · दस्तावेज़ अपलोड करें' },
