  'nsp.loginSub': { en: 'One 14-digit OTR number carries the student through the entire academic career — login once, apply for merit and welfare schemes together.', hi: 'एक 14-अंकीय OTR संख्या छात्र को पूरे शैक्षणिक जीवन ले जाती है — एक बार लॉगिन करें, मेधा व कल्याण योजनाओं हेतु एक साथ आवेदन करें।' },
  'nsp.stall': { en: 'Document upload is where applications stall', hi: 'दस्तावेज़ अपलोड पर आवेदन अटकते हैं' },
  'nsp.stallBody': { en: 'Strict size and format rules block final submission — and a blurred or expired income certificate is the most common reason a nodal officer defects an application.', hi: 'कठोर साइज़ व प्रारूप नियम अंतिम जमा रोकते हैं — और धुंधला या समाप्त आय प्रमाण नोडल अधिकारी द्वारा आवेदन लौटाने का सबसे आम कारण है।' },
  'nsp.loginBox': { en: 'OTR number, Aadhaar-linked mobile OTP.', hi: 'OTR संख्या, आधार-लिंक्ड मोबाइल OTP।' },
