  'nsp.faceAuth': { en: 'NSP OTR App (face auth)', hi: 'NSP OTR ऐप (फेस ऑथ)' },
  'nsp.nudgeEyebrow': { en: 'AY 2026-27 · OTR NSPOTR2026MEERA19', hi: 'शै.व. 2026-27 · OTR NSPOTR2026MEERA19' },
  'nsp.nudgeTitle': { en: '2 documents pending — photo and income certificate block submission', hi: '2 दस्तावेज़ लंबित — फोटो व आय प्रमाण जमा रोकते हैं' },
  'nsp.nudgeDesc': { en: 'NSP needs a photo under 50 KB plus a stamped income-certificate PDF under 500 KB. Open uploads — DocBridge prepares the JPEG and the PDF side by side from DigiLocker.', hi: 'NSP हेतु 50 KB से कम फोटो व 500 KB से कम मोहरयुक्त आय-प्रमाण PDF चाहिए। अपलोड खोलें — DocBridge DigiLocker से JPEG व PDF साथ-साथ तैयार करेगा।' },
  'nsp.nudgeDismissed': { en: 'Nudge dismissed — use the cards below to continue.', hi: 'सूचना हटाई गई — आगे बढ़ने हेतु नीचे के कार्ड उपयोग करें।' },
