  'nsp.schemes': { en: 'Eligible schemes', hi: 'पात्र योजनाएँ' },
  'nsp.openTill': { en: 'Open till 31-10-2026', hi: '31-10-2026 तक खुला' },
  'nsp.app2627': { en: 'Application 2026-27', hi: 'आवेदन 2026-27' },
  'nsp.appTitle': { en: 'One photo, one certificate — two different rulebooks', hi: 'एक फोटो, एक प्रमाणपत्र — दो अलग नियम-पुस्तकें' },
  'nsp.appBody': { en: 'The photo is a tiny JPEG while the income certificate is a stamped PDF up to 500 KB — students usually bounce between a photo resizer and a PDF compressor. DocBridge does both in place.', hi: 'फोटो नन्हा JPEG है जबकि आय प्रमाण 500 KB तक मोहरयुक्त PDF — छात्र प्रायः फोटो रीसाइज़र व PDF कंप्रेसर के बीच भटकते हैं। DocBridge दोनों यहीं करता है।' },
  'nsp.photoBox': { en: 'Photograph · ≤50 KB', hi: 'फोटो · ≤50 KB' },
  'nsp.photoBoxSub': { en: 'JPEG · plain background · face clearly visible.', hi: 'JPEG · सादी पृष्ठभूमि · चेहरा स्पष्ट दिखे।' },
  'nsp.certBox': { en: 'Income certificate · ≤500 KB', hi: 'आय प्रमाणपत्र · ≤500 KB' },
  'nsp.certBoxSub': { en: 'PDF · FY 2026-27 · stamp & signature visible.', hi: 'PDF · वि.व. 2026-27 · मोहर व हस्ताक्षर दिखें।' },
  'nsp.chainTitle': { en: 'Verification chain after submit', hi: 'जमा के बाद सत्यापन श्रृंखला' },
  'nsp.chainBody': { en: 'Institute nodal officer → District → State → PFMS payment. A defect at any level sends the form back to the student.', hi: 'संस्थान नोडल अधिकारी → जिला → राज्य → PFMS भुगतान। किसी भी स्तर की कमी फ़ॉर्म छात्र को लौटा देती है।' },
  'nsp.uploadTitle': { en: 'Upload documents', hi: 'दस्तावेज़ अपलोड करें' },
  'nsp.uploadSub': { en: 'AY 2026-27 · Post-Matric + Merit-cum-Means · only PDF and JPG accepted', hi: 'शै.व. 2026-27 · पोस्ट-मैट्रिक + मेरिट-कम-मीन्स · केवल PDF व JPG स्वीकार्य' },
  'nsp.uploadDocs': { en: 'Upload Document(s)', hi: 'दस्तावेज़ अपलोड करें' },
