  'nsp.pr1': { en: 'Recent passport-size photo, plain background', hi: 'हालिया पासपोर्ट-साइज़ फोटो, सादी पृष्ठभूमि' },
  'nsp.pr2': { en: 'JPEG / JPG only — PNG and HEIC rejected', hi: 'केवल JPEG / JPG — PNG व HEIC अस्वीकृत' },
